using System;
using Spine.Unity;
using UnityEngine;

namespace Astrea;

[Serializable]
public class AnimationState
{
	[SerializeField]
	private AnimationType animationType;

	[SerializeField]
	[SpineAnimation("", "SkeletonDataAssetInternal", true, false)]
	private string animationName;

	[HideInInspector]
	public Sprite ModdedSprite;

	public AnimationState(AnimationType animationType, string animationName)
	{
		this.animationType = animationType;
		this.animationName = animationName;
	}

	public AnimationType GetAnimationType()
	{
		return animationType;
	}

	public string GetAnimationName()
	{
		return animationName;
	}

	public AnimationState(AnimationType animationType, Sprite ModdedSprite)
	{
		this.animationType = animationType;
		this.ModdedSprite = ModdedSprite;
	}
}
